SELECT CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, MAX(ss.sale_date) AS last_sale_date, AVG(ss.revenue) AS avg_revenue FROM store_sales ss LEFT JOIN products p ON p.id = ss.product_id INNER JOIN stores s ON ss.store_id = s.id GROUP BY CASE WHEN YEAR(p.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(p.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END;
